python3 - <<'PYEOF'
import json, subprocess, os
d = json.load(open('outputs/pr_review.json'))
d['issueCounts']['important'] = 2  # changelog-entry finding lives in the general comment
json.dump(d, open('outputs/pr_review.json','w'), indent=2, ensure_ascii=False)

# 1) verify recommendation/severity byte-exact
raw = open('outputs/pr_review.json','rb').read()
assert b'"REQUEST_CHANGES"' in raw, 'recommendation string wrong'
assert raw.count(b'"BLOCKING"') == 3, raw.count(b'"BLOCKING"')
assert raw.count(b'"IMPORTANT"') == 1, raw.count(b'"IMPORTANT"')
assert raw.count(b'"SUGGESTION"') == 2, raw.count(b'"SUGGESTION"')
assert b'"side": "RIGHT"' in raw

# 2) verify every (path,line) is an ADDED line in the right-side diff
diff = subprocess.run(['git','diff','origin/main...HEAD','--unified=0'],
                      capture_output=True, text=True).stdout
cur = None; newmap = {}
for ln in diff.splitlines():
    if ln.startswith('+++ b/'): cur = ln[6:]; newmap[cur] = set()
    elif cur and ln.startswith('+') and not ln.startswith('+++'):
        newmap[cur].add(len(newmap[cur]) or 0)  # placeholder; rebuilt below
# proper rebuild with hunk headers
newmap = {}
cur = None
import re
for ln in diff.splitlines():
    if ln.startswith('+++ b/'): cur = ln[6:]; newmap.setdefault(cur, set())
    elif cur and ln.startswith('@@'):
        m = re.search(r'\+(\d+)(?:,(\d+))?', ln)
        if m:
            start = int(m.group(1)); cnt = int(m.group(2) or 1)
            for i in range(start, start+max(cnt,1)): newmap[cur].add(i)
    elif cur and ln.startswith('+') and not ln.startswith('+++'):
        pass  # line numbers come from hunk headers only when paired; use counters below
# robust approach: walk hunks with counters
newmap = {}; cur=None; n=0
for ln in diff.splitlines():
    if ln.startswith('+++ b/'): cur = ln[6:]; newmap[cur]={}; n=0
    elif cur is None: continue
    elif ln.startswith('@@'):
        m = re.search(r'\+(\d+)', ln); n = int(m.group(1)) - 1
    elif ln.startswith('+') and not ln.startswith('+++'):
        n += 1; newmap[cur].add(n)
    elif ln.startswith('-') and not ln.startswith('---'):
        pass
    else:
        n += 1
fails = []
for c in d['inlineComments']:
    if c['line'] not in newmap.get(c['path'], set()):
        fails.append((c['path'], c['line']))
print('ANCHOR FAILS:', fails or 'none — all 6 anchors are added diff lines')

# 3) general.md consistency
gen = open('outputs/pr_review_general.md').read()
assert '3 blocking' in gen and '2 important' in gen and '2 suggestions' in gen
print('general.md counts consistent; size', len(gen), 'bytes,', gen.count(chr(10)), 'lines')
PYEOF

